import os
print("Checking available experiment variables...")
for i in range(1, 7):
    varname = f"experiment_{i}_csv"
    try:
        path = eval(varname)
        print(f"{varname} = {path}")
        if os.path.exists(path):
            import pandas as pd
            df = pd.read_csv(path)
            print(f"  Columns: {list(df.columns)}")
            print(f"  Shape: {df.shape}")
            print(df.head(2))
        else:
            print(f"  FILE NOT FOUND")
    except NameError:
        print(f"{varname}: variable not defined")
    except Exception as e:
        print(f"{varname}: {type(e).__name__}: {e}")
